def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Non‑numeric elements are ignored. Empty or non‑iterable input returns 0.
    """
    if not nums:
        return 0
    # Ensure iterable
    try:
        _ = iter(nums)
    except TypeError:
        return 0
    import bisect
    tails = []
    for x in nums:
        if not isinstance(x, (int, float)):
            continue
        # Use bisect_left to keep strictly increasing property
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

