def solve(nums):
    a = nums[:]
    n = len(a)
    # find pivot
    i = n - 2
    while i >= 0 and a[i] >= a[i+1]:
        i -= 1
    if i == -1:
        return sorted(a)
    # find rightmost successor
    j = n - 1
    while a[j] <= a[i]:
        j -= 1
    a[i], a[j] = a[j], a[i]
    a[i+1:] = reversed(a[i+1:])
    return a

