def solve(grid):
    # Return 0 for None or empty grid
    if not grid:
        return 0
    # Determine dimensions safely; handle possible empty rows
    m = len(grid)
    n = len(grid[0]) if grid and grid[0] else 0
    # If rows have varying lengths, we treat missing cells as water (0)
    visited = [[False] * n for _ in range(m)]
    def is_land(i, j):
        try:
            val = grid[i][j]
        except Exception:
            return False
        # Accept int 1, string '1', or any truthy non-zero value
        return val == 1 or val == '1' or (isinstance(val, (int, float)) and val != 0) or (isinstance(val, str) and val.strip() == '1')
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny] and is_land(nx, ny):
                    stack.append((nx, ny))
    islands = 0
    for i in range(m):
        for j in range(n):
            if is_land(i, j) and not visited[i][j]:
                islands += 1
                dfs(i, j)
    return islands

